import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import Draggable from "react-draggable";
import { Document, Page, pdfjs } from "react-pdf";
import PageSelectorPopup from "./PageSelectorPopup";

pdfjs.GlobalWorkerOptions.workerSrc = `${process.env.PUBLIC_URL}/pdf.worker.mjs`;

export default function FolderPreviewPopup({ files, onClose, onConfirm }) {
  const [selectedFiles, setSelectedFiles] = useState([]);
  const [previews, setPreviews] = useState([]);
  const [activeFile, setActiveFile] = useState(null);

  useEffect(() => {
    if (files?.length > 0) {
      const mapped = files.map((f) => ({
        name: f.name,
        size: (f.size / 1024 / 1024).toFixed(2) + " MB",
        file: f,
        url: URL.createObjectURL(f),
        pages: [],
      }));

      setPreviews(mapped);
      setSelectedFiles(files.map((f) => f.name));
    }
  }, [files]);

  const toggleFile = (name) => {
    setSelectedFiles((prev) =>
      prev.includes(name)
        ? prev.filter((n) => n !== name)
        : [...prev, name]
    );
  };

  const selectAll = () => {
    if (selectedFiles.length === previews.length) setSelectedFiles([]);
    else setSelectedFiles(previews.map((p) => p.name));
  };

  const handleSavePages = (pages) => {
    setPreviews((prev) =>
      prev.map((p) =>
        p.name === activeFile.name ? { ...p, pages } : p
      )
    );
    setActiveFile(null);
  };

  const handleConfirm = () => {
    const filtered = previews
      .filter((p) => selectedFiles.includes(p.name))
      .map((p) => ({
        ...p,
        selectedPages: p.pages || [],
      }));

    onConfirm(filtered);
  };

  return createPortal(
    <>
      <Draggable handle=".modal-header">
        <div
          className="popup__count"
          style={{
            zIndex: 9999,
            position: "fixed",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            width: "90%",
            maxWidth: "1000px",
            background: "#fff",
            borderRadius: "8px",
            boxShadow: "0 8px 32px rgba(0,0,0,0.3)",
            overflow: "hidden",
          }}
        >
          {/* HEADER */}
          <div
            className="modal-header"
            style={{
              background: "#343a40",
              color: "#fff",
              cursor: "move",
              padding: "10px 15px",
              fontWeight: "bold",
            }}
          >
            Vista previa de carpeta
            <span
              onClick={onClose}
              style={{
                cursor: "pointer",
                float: "right",
                fontSize: "18px",
                fontWeight: "bold",
              }}
            >
              ×
            </span>
          </div>

          {/* BODY */}
          <div
            className="modal-body"
            style={{
              maxHeight: "70vh",
              overflowY: "auto",
              background: "#f8f9fa",
              padding: "15px",
            }}
          >
            <div style={{ textAlign: "center", marginBottom: "10px" }}>
              <button
                onClick={selectAll}
                style={{
                  background: "transparent",
                  border: "1px solid #0d6efd",
                  color: "#0d6efd",
                  padding: "6px 12px",
                  borderRadius: "4px",
                  cursor: "pointer",
                }}
              >
                {selectedFiles.length === previews.length
                  ? "Deseleccionar todos"
                  : "Seleccionar todos"}
              </button>
            </div>

            <div
              style={{
                display: "flex",
                flexWrap: "wrap",
                justifyContent: "center",
                gap: "15px",
              }}
            >
              {previews.map((p, index) => (
                <div
                  key={index}
                  style={{
                    width: "180px",
                    border: selectedFiles.includes(p.name)
                      ? "2px solid #0d6efd"
                      : "1px solid #ccc",
                    borderRadius: "8px",
                    background: "#fff",
                    boxShadow: "0 2px 8px rgba(0,0,0,0.1)",
                    padding: "10px",
                    textAlign: "center",
                    cursor: "pointer",
                  }}
                  onClick={() => setActiveFile(p)}
                >
                  <h6
                    style={{
                      fontSize: "12px",
                      whiteSpace: "nowrap",
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      marginBottom: "6px",
                    }}
                    title={p.name}
                  >
                    {p.name}
                  </h6>

                  <p style={{ fontSize: "11px", color: "#666", margin: "0" }}>
                    {p.size}
                  </p>

                  <Document
                    file={p.url}
                    loading={<p>Cargando...</p>}
                    error={<p>Failed to load PDF file.</p>}
                  >
                    <Page
                      pageNumber={1}
                      width={140}
                      renderTextLayer={false}
                      renderAnnotationLayer={false}
                    />
                  </Document>

                  <label
                    style={{ fontSize: "12px", cursor: "pointer" }}
                    onClick={(e) => e.stopPropagation()}
                  >
                    <input
                      type="checkbox"
                      checked={selectedFiles.includes(p.name)}
                      onChange={() => toggleFile(p.name)}
                      style={{ marginRight: "4px" }}
                    />
                    Seleccionar
                  </label>
                </div>
              ))}
            </div>
          </div>

          {/* FOOTER */}
          <div
            className="modal-footer"
            style={{
              display: "flex",
              justifyContent: "flex-end",
              gap: "10px",
              background: "#f1f1f1",
              borderTop: "1px solid #ccc",
              padding: "10px 15px",
            }}
          >
            <button
              onClick={onClose}
              style={{
                background: "#6c757d",
                border: "none",
                color: "#fff",
                padding: "6px 12px",
                borderRadius: "4px",
                cursor: "pointer",
              }}
            >
              Cancelar
            </button>

            <button
              onClick={handleConfirm}
              style={{
                background: "#0d6efd",
                border: "none",
                color: "#fff",
                padding: "6px 12px",
                borderRadius: "4px",
                cursor: "pointer",
              }}
            >
              Subir seleccionados ({selectedFiles.length})
            </button>
          </div>
        </div>
      </Draggable>

      {activeFile && (
        <PageSelectorPopup
          file={activeFile}
          onClose={() => setActiveFile(null)}
          onSave={handleSavePages}
        />
      )}
    </>,
    document.getElementById("root")
  );
}
