import { db } from "./db";
import { routes } from "../Constants";

export async function syncDrawings() {
  const lastRecord = await db.drawings.orderBy("updated_at").last();
  const lastUpdated = lastRecord ? lastRecord.updated_at : null;

  const response = await fetch("/api/pullUpdates/drawings", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Authorization": `Bearer ${routes.__token}`,
    },
    body: JSON.stringify({ last_updated_at: lastUpdated }),
  });

  const data = await response.json();

  if (data && data.records) {
    const parsedRecords = data.records.map(record => {
      return {
        ...record,
        // 🔹 Si están en string, conviértelos a objeto/array
        scale: typeof record.scale === "string" ? record.scale.replace(/`/g, "") : record.scale,
        area: typeof record.area === "string" ? JSON.parse(record.area) : record.area,
        perimeter: typeof record.perimeter === "string" ? JSON.parse(record.perimeter) : record.perimeter,
        lines: typeof record.line === "string" ? JSON.parse(record.line) : record.line,
      };
    });

    await db.drawings.bulkPut(parsedRecords);
    console.log("✅ Drawings sincronizados:", parsedRecords.length);
  }
}
