import React, { useEffect, useRef, useState } from "react";
import { toast } from "react-toastify";
import useSignal from "../hooks/signals";
import { projectId, routes, MAX_FILE_SIZE, MAX_FILE_SIZE_MB } from "../Constants";
import axios from "axios";
import FolderPreviewPopup from "./FolderPreviewPopup"; // 👈 tu popup nuevo

const FolderUpload = () => {
  const signal = useSignal();
  const inputRef = useRef(null);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [uploading, setUploading] = useState(false);
  const [selectedFiles, setSelectedFiles] = useState([]);
  const [showPreview, setShowPreview] = useState(false);

  // =============== LOADING OVERLAY (igual que antes) ===============
  useEffect(() => {
    let loadingOverlay = document.getElementById("loadingOverlay");

    if (!loadingOverlay) {
      loadingOverlay = document.createElement("div");
      loadingOverlay.id = "loadingOverlay";

      Object.assign(loadingOverlay.style, {
        position: "absolute",
        top: "50%",
        left: "50%",
        transform: "translate(-50%, -50%)",
        background: "rgba(255, 255, 255, 0.25)",
        backdropFilter: "blur(10px)",
        WebkitBackdropFilter: "blur(10px)",
        borderRadius: "16px",
        padding: "40px 60px",
        textAlign: "center",
        color: "#fff",
        fontFamily: "Inter, sans-serif",
        boxShadow: "0 8px 32px rgba(31,38,135,0.37)",
        border: "1px solid rgba(255,255,255,0.3)",
        zIndex: "9999",
        minWidth: "380px",
        display: "none",
        opacity: "0",
        transition: "opacity 0.5s ease",
      });

      document.querySelector(".drawing-board__container")?.appendChild(loadingOverlay);
    }

    if (uploading) {
      loadingOverlay.style.display = "block";
      setTimeout(() => (loadingOverlay.style.opacity = "1"), 50);
    } else {
      loadingOverlay.style.opacity = "0";
      setTimeout(() => (loadingOverlay.style.display = "none"), 500);
    }
  }, [uploading]);

  // =============== LLAMADO DESDE MENÚ ===============
  useEffect(() => {
    // para poder llamarlo desde el menú principal con window.triggerFolderUpload()
    window.triggerFolderUpload = () => {
      if (inputRef.current) {
        inputRef.current.setAttribute("webkitdirectory", "");
        inputRef.current.setAttribute("directory", "");
        inputRef.current.click();
      }
    };
  }, []);

  // =============== CUANDO SELECCIONAN CARPETA ===============
  const handleFolderSelect = (e) => {
    const files = Array.from(e.target.files).filter((f) => f.name.toLowerCase().endsWith(".pdf"));
    if (files.length === 0) {
      toast.warning("⚠️ No se encontraron archivos PDF en la carpeta seleccionada.");
      return;
    }
    setSelectedFiles(files);
    setShowPreview(true); // 👈 abrimos popup de previsualización
  };

  // =============== PROCESO DE SUBIDA (con tus estilos) ===============
  const handleUploadConfirmed = async (filesWithPages) => {
    setShowPreview(false);
    setUploading(true);
    const overlay = document.getElementById("loadingOverlay");

    for (const [index, fileData] of Object.entries(filesWithPages)) {
      const file = fileData.file;

      if (file.size > MAX_FILE_SIZE) {
        toast.error(
          `⚠️ "${file.name}" excede el tamaño máximo permitido (${MAX_FILE_SIZE_MB} MB).`
        );
        continue;
      }

      const formData = new FormData();
      formData.append("file", file);
      formData.append("project_id", projectId);
      formData.append("path", file.webkitRelativePath || file.name);

      // Si hay páginas seleccionadas, enviarlas también
      if (fileData.pages && fileData.pages.length > 0) {
        formData.append("pages", JSON.stringify(fileData.pages));
      }

      overlay.innerHTML = `
        <h3 style="margin-bottom: 10px; font-weight: 600;">Uploading file ${parseInt(index) + 1} of ${filesWithPages.length}</h3>
        <p style="margin: 0 0 6px 0; font-size: 15px;">${file.name}</p>
        <p style="font-size: 12px; opacity: 0.8;">${(file.size / 1024 / 1024).toFixed(2)} MB</p>
        <progress value="0" max="100" style="width: 300px; height: 14px; border-radius: 8px; overflow: hidden;"></progress>
        <p id="progressText" style="margin-top: 8px; font-size: 13px;">0%</p>
      `;

      const progressBar = overlay.querySelector("progress");
      const progressText = overlay.querySelector("#progressText");

      try {
        await axios.post(routes.upload, formData, {
          headers: { Authorization: `Bearer ${routes.__token}` },
          onUploadProgress: (e) => {
            const progress = Math.round((e.loaded * 100) / e.total);
            progressBar.value = progress;
            progressText.textContent = `${progress}%`;
            setUploadProgress(progress);
          },
        });

        overlay.innerHTML = `
          <h3 style="margin-bottom: 15px; font-weight: 600;">Processing file ${parseInt(index) + 1} of ${filesWithPages.length}</h3>
          <p style="font-size: 14px; margin-bottom: 15px;">${file.name}</p>
          <div class="spinner-border text-light" style="width: 3rem; height: 3rem;" role="status"></div>
        `;
        await new Promise((res) => setTimeout(res, 900));
      } catch (error) {
        console.error("❌ Upload error:", error);
        let errorMsg =
          error.response?.data?.message ||
          error.response?.statusText ||
          error.message ||
          "Unknown error";

        overlay.innerHTML = `
          <h3 style="margin-bottom: 10px; color:#ffbaba;">❌ Upload Failed</h3>
          <p style="margin: 0 0 10px 0; font-size: 15px; color:#ffbaba;">${file.name}</p>
          <p style="font-size: 13px; color:#ffbaba;">${errorMsg}</p>
        `;

        toast.error(`❌ Error uploading "${file.name}": ${errorMsg}`);
        await new Promise((res) => setTimeout(res, 1800));
      }
    }

    setUploading(false);
    setUploadProgress(0);
    signal.emit("refresh");
  };

  return (
    <div>
      <input
        ref={inputRef}
        type="file"
        className="hidden"
        onChange={handleFolderSelect}
        id="folderUpload"
        webkitdirectory="true"
        mozdirectory="true"
        multiple
        accept=".pdf"
      />

      {showPreview && (
        <FolderPreviewPopup
          files={selectedFiles}
          onClose={() => setShowPreview(false)}
          onConfirm={handleUploadConfirmed}
        />
      )}
    </div>
  );
};

export default FolderUpload;
