import { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import FileContext from "./FileContext";
import { routes } from "../Constants";
import "../proposalpopup.css";
import ProjectMeasurement from "./ProjectMeasurement";
import { pdfjs } from "react-pdf";

pdfjs.GlobalWorkerOptions.workerSrc = `${process.env.PUBLIC_URL}/pdf.worker.mjs`;

/* ============================================================
   UTILS
============================================================ */
function fileName(planPath) {
  const arr = String(planPath || "").split("/");
  const leaf = arr[arr.length - 1] || "";
  return leaf.replace(/\.(svg|pdf|png|jpg|jpeg|webp)$/i, "");
}

function normalizePlanPath(plan) {
  let fixed = String(plan || "");
  fixed = fixed.startsWith("uploads/") ? fixed : `uploads/${fixed}`;
  fixed = fixed.replace(/^uploads\/uploads\//, "uploads/");
  return fixed;
}

function isImagePath(path) {
  const lower = String(path || "").toLowerCase();
  return (
    lower.endsWith(".png") ||
    lower.endsWith(".svg") ||
    lower.endsWith(".jpg") ||
    lower.endsWith(".jpeg") ||
    lower.endsWith(".webp")
  );
}

function isPdfPath(path) {
  return String(path || "").toLowerCase().endsWith(".pdf");
}

function sanitizePrefixFromPdfName(pdfName) {
  return String(pdfName || "document.pdf").replace(/\.pdf$/i, "");
}

// extrae project_id y pdfName desde: uploads/projects/project123/Plano.pdf
function parseProjectAndFileFromPlanPath(fixedPlan) {
  const parts = String(fixedPlan || "").split("/");
  const projectFolder = parts[2] || ""; // project123
  const baseFileName = parts[3] || ""; // Plano.pdf

  const projectIdStr = projectFolder.replace("project", "");
  const prefix = sanitizePrefixFromPdfName(baseFileName);

  return { projectFolder, projectIdStr, baseFileName, prefix };
}

function parseThumbMetaFromUrl(previewUrl) {
  const leaf = decodeURIComponent(String(previewUrl || "").split("/").pop() || "");

  let code = null;
  const mCode = leaf.match(/__(.+?)__P\d+\.(png|jpg|jpeg|webp)$/i);
  if (mCode && mCode[1]) code = mCode[1];

  let page = null;
  const mPage = leaf.match(/__P(\d+)\.(png|jpg|jpeg|webp)$/i);
  if (mPage && mPage[1]) page = parseInt(mPage[1], 10);

  return { leaf, code, page };
}

// "uploads/projects/project81/owensboro.pdf" → url completo
function buildPdfUrlFromPlan(plan) {
  const fixedPlan = normalizePlanPath(plan);
  return `${routes.webUrl}/${fixedPlan}`;
}

function parsePageFromLeaf(leaf) {
  const clean = decodeURIComponent(String(leaf || "").split("?")[0]); // ✅ quita ?quality=...
  const m = clean.match(/__P(\d+)\.(png|jpg|jpeg|webp)$/i);
  return m ? parseInt(m[1], 10) : null;
}

// generar PNG full (scale 2.8) para una página del PDF
async function renderPdfPageToPngFile({ pdfUrl, pageNumber, filename, scale = 2.8 }) {
  const task = pdfjs.getDocument({ url: pdfUrl });
  const pdf = await task.promise;

  const page = await pdf.getPage(pageNumber);
  const viewport = page.getViewport({ scale });

  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");

  canvas.width = viewport.width;
  canvas.height = viewport.height;

  await page.render({ canvasContext: ctx, viewport }).promise;

  const blob = await new Promise((resolve, reject) => {
    canvas.toBlob(
      (b) => (b ? resolve(b) : reject(new Error("No se pudo generar PNG"))),
      "image/png"
    );
  });

  return new File([blob], filename, { type: "image/png" });
}

/* ============================================================
   MAIN
============================================================ */
function FileView({ plans }) {
  const navigate = useNavigate();

  const [context, setContext] = useState(null);
  const [isProjectMeasurementOpen, setIsProjectMeasurementOpen] = useState(false);

  // previewImages[plan] = array de URLs (pngs) o [url] si plan es imagen
  const [previewImages, setPreviewImages] = useState({});

  // estado de carga por plan
  const [processingState, setProcessingState] = useState({});

  // loader por thumbnail cuando hace "full exists / create full"
  const [openingState, setOpeningState] = useState({});

  const handleContext = (e, plan) => {
    e.preventDefault();
    setContext({ x: e.clientX, y: e.clientY, plan });
  };

  const toggleProjectMeasurement = () =>
    setIsProjectMeasurementOpen(!isProjectMeasurementOpen);

  /* ============================================================
     Cargar previews:
     - Si plan es imagen: usarla
     - Si plan es PDF: pedir PNGs existentes (NO mostrar el PDF)
  ============================================================ */
  const loadPreviewsForPlan = async (plan) => {
    const fixedPlan = normalizePlanPath(plan);
    const lower = fixedPlan.toLowerCase();

    setProcessingState((prev) => ({
      ...prev,
      [plan]: { total: 1, current: 0, done: false, flash: false },
    }));
    setPreviewImages((prev) => ({ ...prev, [plan]: [] }));

    // 1) Si es imagen: mostrar directo
    if (isImagePath(lower)) {
      const url = `${routes.webUrl}/${fixedPlan}`;
      setPreviewImages((prev) => ({ ...prev, [plan]: [url] }));
      setProcessingState((prev) => ({
        ...prev,
        [plan]: { total: 1, current: 1, done: true, flash: true },
      }));
      setTimeout(() => {
        setProcessingState((prev) => ({
          ...prev,
          [plan]: { ...prev[plan], flash: false },
        }));
      }, 900);
      return;
    }

    // 2) Si NO es PDF: no mostramos nada
    if (!isPdfPath(lower)) {
      setProcessingState((prev) => ({
        ...prev,
        [plan]: { total: 1, current: 1, done: true, flash: false },
      }));
      return;
    }

    // 3) Si es PDF: lista pngs existentes (thumb)
    const { projectIdStr, prefix } = parseProjectAndFileFromPlanPath(fixedPlan);

    const listUrl = `${routes.list_plan_images}?project=${encodeURIComponent(
      projectIdStr
    )}&prefix=${encodeURIComponent(prefix)}`;

    try {
      const resp = await fetch(listUrl, {
        headers: { Authorization: `Bearer ${routes.__token}` },
      });

      const data = await resp.json();
      const paths = Array.isArray(data) ? data : [];

      const urls = paths
        .filter(Boolean)
        .map((p) => (String(p).startsWith("http") ? p : `${routes.webUrl}/${p}`));

      setPreviewImages((prev) => ({ ...prev, [plan]: urls }));
      setProcessingState((prev) => ({
        ...prev,
        [plan]: {
          total: Math.max(urls.length, 1),
          current: Math.max(urls.length, 1),
          done: true,
          flash: true,
        },
      }));

      setTimeout(() => {
        setProcessingState((prev) => ({
          ...prev,
          [plan]: { ...prev[plan], flash: false },
        }));
      }, 900);
    } catch (e) {
      console.warn("No se pudieron listar previews:", e);
      setPreviewImages((prev) => ({ ...prev, [plan]: [] }));
      setProcessingState((prev) => ({
        ...prev,
        [plan]: { total: 1, current: 1, done: true, flash: false },
      }));
    }
  };

  useEffect(() => {
    if (!Array.isArray(plans)) return;
    plans.forEach((plan) => loadPreviewsForPlan(plan));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [plans]);

  /* ============================================================
     CLICK: si FULL existe -> abre viewer normal (SPA) con quality=full
            si no existe -> genera PNG (React) -> upload -> abre viewer normal
     IMPORTANTE: NO usamos window.location.href para no salir del SPA
  ============================================================ */
  async function existsUrl(url) {
    const r = await fetch(url, { method: "HEAD" });
    return r.ok;
  }

  const handleOpenOrCreateFull = async (e, plan, previewUrl, viewerURL) => {
    e.preventDefault(); // detenemos la navegación inmediata del <Link>

    const fixedPlan = normalizePlanPath(plan);
    const { projectIdStr, projectFolder } = parseProjectAndFileFromPlanPath(fixedPlan);

    const { leaf } = parseThumbMetaFromUrl(previewUrl);
    const page = parsePageFromLeaf(leaf);

    const openKey = `${projectFolder}::${leaf}`;
    setOpeningState((prev) => ({ ...prev, [openKey]: true }));

    const thumbRoute = `/projects/${projectFolder}/thumb/${encodeURIComponent(leaf)}`;
    const fullRoute  = `/projects/${projectFolder}/full/${encodeURIComponent(leaf)}`;
    const legacyRoute = `/projects/${projectFolder}/${encodeURIComponent(leaf)}`;

    try {
      // 1) full-exists
      const existsUrl =
        `${routes.full_exists}?project_id=${encodeURIComponent(projectIdStr)}` +
        `&file=${encodeURIComponent(leaf)}`;

      const resp = await fetch(existsUrl, {
        headers: {
          Authorization: `Bearer ${routes.__token}`,
          Accept: "application/json",
        },
      });

      const data = await resp.json().catch(() => null);

      if (data?.exists) {
        // ✅ abre dentro del SPA como antes
        navigate(fullRoute);
        return;
      }

      // 2) si no hay page, no podemos generar: abre thumb dentro del SPA
      if (!page || Number.isNaN(page) || page < 1) {
        console.log('no tiene page')
        if (await existsUrl(routes.public + thumbRoute)) {
          navigate(thumbRoute);
          return;
        }
        if (await existsUrl(routes.public + legacyRoute)) {
          navigate(legacyRoute);
          return;
        }
      }

      // 3) generar PNG full en React
      console.log(page);
      const pdfUrl = buildPdfUrlFromPlan(plan);
      const fullPngFile = await renderPdfPageToPngFile({
        pdfUrl,
        pageNumber: page,
        filename: leaf, // MISMO nombre que thumb
        scale: 2.8,
      });

      // 4) subir PNG full
      const fd = new FormData();
      fd.append("project_id", projectIdStr);
      fd.append("png", fullPngFile); // backend espera 'png'

      const up = await fetch(routes.create_full_page, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${routes.__token}`,
          Accept: "application/json",
        },
        body: fd,
      });

      const upData = await up.json().catch(() => null);

      if (!up.ok || !upData?.ok) {
        throw new Error(upData?.message || upData?.error || "No se pudo subir la imagen full");
      }

      // 5) abrir dentro del SPA como antes
      navigate(fullRoute);
    } catch (err) {
      console.error("❌ Error creando/abriendo FULL:", err);
      // fallback SPA

      if (await existsUrl(routes.public + thumbRoute)) {
        navigate(thumbRoute);
      }
      if (await existsUrl(routes.public + legacyRoute)) {
        navigate(legacyRoute);
      }
    } finally {
      setOpeningState((prev) => ({ ...prev, [openKey]: false }));
    }
  };

  /* ============================================================
     RENDER
  ============================================================ */
  return (
    <>
      <button
        className="text-black text-14 d-inline-block return-projects-btn"
        onClick={() => (window.location.href = `${routes.webUrl}/project`)}
      >
        Return to Project list
      </button>

      <button
        className="text-black text-14 d-inline-block measurement-btn"
        onClick={toggleProjectMeasurement}
      >
        Open Project Measurement
      </button>

      {isProjectMeasurementOpen && <ProjectMeasurement plans={plans} />}

      <details className="tool__box" open>
        <summary>
          <div className="tool__box-header">
            <i className="fa fa-folder"></i> Plans and Documents
          </div>
        </summary>

        {/* SOLO RENDERIZA IMÁGENES (PNGs/otras), NO PDFs */}
        {plans.flatMap((plan) => {
          const urls = previewImages[plan] || [];
          if (!urls.length) return [];

          const fixedPlan = normalizePlanPath(plan);
          const { projectFolder } = parseProjectAndFileFromPlanPath(fixedPlan);

          const prog = processingState[plan] || {};
          const isDone = !!prog.done;

          return urls.map((previewUrl, idx) => {
            const leaf = decodeURIComponent(String(previewUrl).split("/").pop() || "");

            // ✅ IMPORTANTE: ruta RELATIVA (sin "/" inicial) para que funcione en /81/application
            const viewerURL = `projects/${projectFolder}/${leaf}`;

            const openKey = `${projectFolder}::${leaf}`;
            const isOpening = !!openingState[openKey];

            return (
              <Link
                key={plan + "-" + idx}
                to={viewerURL}
                onClick={(e) => handleOpenOrCreateFull(e, plan, previewUrl, viewerURL)}
                onContextMenu={(e) => handleContext(e, plan)}
                className="file__view d-flex flex-column align-items-center justify-content-center text-center mb-3 p-2 rounded"
              >
                <div
                  className={
                    "file-thumb mb-2 border d-flex align-items-center justify-content-center position-relative " +
                    (prog.flash ? "border-flash" : "")
                  }
                  style={{
                    width: "130px",
                    height: "130px",
                    overflow: "hidden",
                    borderRadius: "8px",
                    backgroundColor: "#f8f9fa",
                    boxShadow: "0 2px 6px rgba(0,0,0,0.15)",
                    border: isDone ? "3px solid #0d6efd" : "2px dashed #aaa",
                  }}
                >
                  {!isDone && idx === 0 && (
                    <div
                      className="spinner-border text-primary position-absolute"
                      style={{ width: "30px", height: "30px" }}
                    ></div>
                  )}

                  {isOpening && (
                    <div
                      className="spinner-border text-primary position-absolute"
                      style={{ width: "30px", height: "30px" }}
                    ></div>
                  )}

                  <img
                    src={previewUrl}
                    alt={leaf}
                    style={{
                      maxWidth: "95%",
                      maxHeight: "95%",
                      objectFit: "contain",
                      opacity: isOpening ? 0.45 : isDone ? 1 : 0.4,
                    }}
                  />
                </div>

                <div className="file-info text-center">
                  <i className="fa fa-file-text-o text-secondary me-2"></i>
                  {(() => {
                    const { code, page } = parseThumbMetaFromUrl(previewUrl);
                    const label = code ? code : page ? `PAGE-${page}` : "";
                    return (
                      <span style={{ fontSize: "14px" }}>
                        {fileName(plan)}
                        {label ? <span style={{ color: "#0d6efd" }}> — {label}</span> : null}
                      </span>
                    );
                  })()}
                </div>
              </Link>
            );
          });
        })}
      </details>

      {context && <FileContext details={context} />}
    </>
  );
}

export default FileView;
